'use strict';
const http=require('node:http');
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
// Private SMTP and read-only PocketBase settings from a non-public .env file.
if(typeof process.loadEnvFile==='function'&&fs.existsSync(path.join(__dirname,'.env')))process.loadEnvFile(path.join(__dirname,'.env'));
const {URL}=require('node:url');
const {db,getSettings,entries,getEntry,DATA_DIR}=require('./db');
const {verifyPassword}=require('./scripts');
const cvSync=require('./cv-sync');
const {cvPDF}=require('./pdf');
const mail=require('./mail');
const PORT=Number(process.env.PORT||3090),HOST=process.env.HOST||'127.0.0.1';
const ROOT=path.join(__dirname,'public');
const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const slugify=s=>String(s||'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,90)||'untitled';
const tags=s=>String(s||'').split(',').map(x=>x.trim()).filter(Boolean);
const badge=(s,cls='')=>`<span class="chip ${cls}">${esc(s)}</span>`;
const pilltags=(s)=>tags(s).map(t=>badge(t)).join('');
const routeNames={ '/':'Home','/posts':'Posts','/portfolio':'Portfolio','/tools':'Tools','/about':'About','/cv':'CV','/contact':'Contact'};
const icons={search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',moon:'<path d="M20.6 14A9 9 0 0 1 10 3.4 9 9 0 1 0 20.6 14Z"/>',arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',down:'<path d="M12 4v16m-6-6 6 6 6-6"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',github:'<path d="M9 19c-4 1-4-2-6-2m12 4v-3.9a3.4 3.4 0 0 0-1-2.6c3.3-.4 6.8-1.6 6.8-7.5a5.8 5.8 0 0 0-1.6-4c.2-.7.7-2.2-.2-4.1 0 0-1.3-.4-4.2 1.6a14.6 14.6 0 0 0-7.6 0C4.3-.5 3-.1 3-.1c-.9 1.9-.4 3.4-.2 4.1A5.8 5.8 0 0 0 1.2 8c0 5.9 3.5 7.1 6.8 7.5a3.4 3.4 0 0 0-1 2.6V21"/>',folder:'<path d="M3 6h6l2 2h10v11H3z"/>',terminal:'<path d="m4 6 6 6-6 6m9 0h7"/>',shield:'<path d="M12 2 20 6v6c0 5-3 8-8 10-5-2-8-5-8-10V6z"/>',network:'<circle cx="6" cy="6" r="2"/><circle cx="18" cy="6" r="2"/><circle cx="12" cy="18" r="2"/><path d="m8 7 3 9m5-9-3 9M8 6h8"/>',code:'<path d="m8 8-4 4 4 4m8-8 4 4-4 4m-3-12-2 16"/>',cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 1v5m6-5v5M9 18v5m6-5v5M1 9h5m-5 6h5m12-6h5m-5 6h5"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4H4v12h4"/>',check:'<path d="m4 12 5 5L20 6"/>',external:'<path d="M13 4h7v7m0-7-9 9"/><path d="M20 13v7H4V4h7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 7 9-7"/>',logout:'<path d="M9 4H4v16h5m4-12 4 4-4 4m-7-4h11"/>'};
const icon=(name,size=15)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.code}</svg>`;
function plainMarkdown(md){ const lines=String(md||'').split(/\r?\n/);let out='',inList=false;
 const inline=t=>esc(t).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/`([^`]+)`/g,'<code>$1</code>');
 for(const raw of lines){let t=raw.trim();if(t.startsWith('- ')){if(!inList){out+='<ul>';inList=true;}out+=`<li>${inline(t.slice(2))}</li>`;continue;}if(inList){out+='</ul>';inList=false;}if(!t)continue;if(t.startsWith('### '))out+=`<h3>${inline(t.slice(4))}</h3>`;else if(t.startsWith('## '))out+=`<h2>${inline(t.slice(3))}</h2>`;else if(t.startsWith('# '))out+=`<h1>${inline(t.slice(2))}</h1>`;else out+=`<p>${inline(t)}</p>`;}
 if(inList)out+='</ul>';return out;
}
function safeUrl(v){try{const u=new URL(String(v));return ['https:','http:','mailto:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function linkout(url,label,cls=''){const u=safeUrl(url);return u?`<a class="${cls}" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${label}</a>`:'';}
function siteHeader(site,active='Home'){
 const nav=Object.entries(routeNames).map(([href,title])=>`<a href="${href}" class="nav-link ${active===title?'active':''}" ${active===title?'aria-current="page"':''}>${title}</a>`).join('');
 return `<header class="site-header"><div class="nav-shell"><a href="/" class="brand" aria-label="Febro Herdyanto homepage"><span class="brand-mark">fh</span><span class="brand-path">~/febro</span></a><nav class="main-nav" id="main-nav" aria-label="Main navigation">${nav}</nav><div class="nav-actions"><button class="icon-button search-launch" type="button" aria-label="Search the site">${icon('search',16)}<span class="kbd">⌘ K</span></button><button class="icon-button theme-toggle" type="button" aria-label="Toggle color theme"><span class="theme-moon">${icon('moon',16)}</span><span class="theme-sun">${icon('sun',16)}</span></button><button class="icon-button menu-toggle" type="button" aria-label="Toggle menu" aria-expanded="false">${icon('menu',18)}</button></div></div></header>`;
}
function footer(site){return `<footer class="site-footer"><div class="footer-container"><div class="footer-top"><div><a class="brand" href="/"><span class="brand-mark">fh</span><span class="brand-path">~/febro</span></a><p>${esc(site.site_tagline)}<br>Writing about practical technology and projects.</p></div><div><span class="footer-title">pages</span><div class="footer-links"><a href="/">Home</a><a href="/posts">Blog</a><a href="/portfolio">Portfolio</a><a href="/tools">Tools</a><a href="/cv">CV</a><a href="/contact">Contact</a></div></div><div><span class="footer-title">connect</span><div class="footer-social">${linkout(site.github,icon('github'),'social-button')}${site.linkedin?linkout(site.linkedin,'in','social-button'):''}<a class="social-button" href="mailto:${esc(site.email)}" aria-label="Email">${icon('mail')}</a></div></div></div></div><div class="footer-credit"><div class="footer-container"><span>© ${new Date().getFullYear()} ${esc(site.site_name)} · all systems normal</span><span>${esc(site.footer_note)}</span></div></div></footer>`;}
function page({site,title='',desc='',body='',active='',pathName='/',hero=false,robots='',extraHead=''}){
 const pageTitle=title?`${title} — ${site.site_name}`:`${site.site_name} — ${site.site_tagline}`;
 const description=desc||site.hero_description;const canonical=safeUrl((site.website||'https://febro.id').replace(/\/$/,'')+pathName);
 const structured=JSON.stringify({'@context':'https://schema.org','@type':'Person',name:site.site_name,url:site.website,description:site.hero_description}).replace(/</g,'\\u003c');
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#edf2fa"><meta name="description" content="${esc(description)}"><title>${esc(pageTitle)}</title><link rel="canonical" href="${esc(canonical)}"><meta property="og:title" content="${esc(pageTitle)}"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="website"><meta property="og:url" content="${esc(canonical)}">${robots?`<meta name="robots" content="${esc(robots)}">`:''}<link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/app.css?v=1.4.0"><script>try{document.documentElement.dataset.theme=localStorage.getItem('fh-theme')||'light'}catch(e){document.documentElement.dataset.theme='light'}</script><script type="application/ld+json">${structured}</script>${extraHead}</head><body>${siteHeader(site,active)}${hero?'<canvas id="particle-canvas" aria-hidden="true"></canvas>':''}<div class="site-wrapper">${body}</div>${footer(site)}<div class="search-overlay" id="search-overlay" aria-hidden="true"><div class="search-dialog" role="dialog" aria-label="Search website" aria-modal="true"><div class="search-dialog-head">${icon('search',18)}<input id="global-search" type="search" placeholder="Search posts, projects, tools, pages..." aria-label="Search all content" autocomplete="off"><button class="key-hint" id="search-close">ESC</button></div><div class="search-results" id="search-results"></div><div class="search-dialog-foot">Use ↑ ↓ to navigate · Enter to open · ESC to close</div></div></div><script src="/app.js?v=1.4.0" defer></script></body></html>`;
}
function titleBlock(eyebrow,title,desc){return `<div class="page-heading"><div class="eyebrow">// ${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>`;}
function sectionHead(label,title,url){return `<div class="section-head"><div><div class="eyebrow">// ${esc(label)}</div><h2>${esc(title)}</h2></div><a href="${url}" class="section-more">all ${icon('arrow',11)}</a></div>`;}
function avatar(site,small=false){return site.avatar?`<img src="${esc(site.avatar)}" class="${small?'small-avatar':'hero-avatar-img'}" alt="Portrait of ${esc(site.site_name)}">`:`<div class="${small?'small-avatar placeholder-avatar':'avatar-placeholder'}" aria-label="Profile picture placeholder"><span>FH</span></div>`;}
const TOOL_IDS=new Set('ip-calculator dns-records http-status json-formatter password-generator uuid-generator unix-timestamp text-tools voltage-current ohms-law ac-power three-phase-power motor-current voltage-drop energy-cost'.split(' '));
const visibleTools=()=>entries('tool').filter(x=>TOOL_IDS.has(x.slug));
const getCategories=()=>db.prepare('SELECT * FROM project_categories ORDER BY sort_order ASC,id ASC').all();
function accessMode(item){if(!item.id)return 'view_only';return ['view_only','detail','external'].includes(item.access_mode)?item.access_mode:(item.company?'view_only':item.url?'external':'detail');}
function projectLink(item){const mode=accessMode(item);if(mode==='detail')return '/portfolio/'+item.slug;return mode==='external'?safeUrl(item.url):'';}
function projectCard(item,i){const href=projectLink(item),body=`<span class="project-number">${String(i+1).padStart(2,'0')}</span><div class="project-meta">${badge(item.category,'blue-chip')} <span class="mini-year">${esc(item.year)}</span>${item.featured?'<span class="featured-tag">★ featured</span>':''}</div><h2>${esc(item.title)}</h2>${item.company?`<div class="project-company">${esc(item.company)}</div>`:''}<p>${esc(item.description)}</p><div class="tag-row">${pilltags(item.tags)}</div>${href?`<span class="project-action">${accessMode(item)==='external'?'Live preview ↗':'Open details →'}</span>`:''}`;
 return href?`<a class="project-card" href="${esc(href)}" ${accessMode(item)==='external'?'target="_blank" rel="noopener noreferrer"':''}>${body}</a>`:`<article class="project-card project-static" aria-label="${esc(item.title)}, overview only">${body}</article>`;
}
function postCard(item,compact=false){return `<a class="post-item ${compact?'post-compact':''}" href="/posts/${esc(item.slug)}"><span class="post-orange"></span><div class="post-content"><div class="post-meta">${esc(item.category||'Writing')} · ${esc(item.year||'2026')} · ${Math.max(2,Math.ceil((item.body||item.description).split(/\s+/).length/220))} min read ${compact?'':`· ${item.views} views`}</div><strong>${esc(item.title)}</strong>${!compact?`<p>${esc(item.description)}</p>`:''}</div><span class="post-tags">${!compact?pilltags(item.tags):icon('arrow',13)}</span></a>`;}
function home(site){const projects=entries('project').slice(0,3),posts=entries('post').slice(0,3),tools=visibleTools();const count=entries('project').length;
 const stats=[[String(tools.length),'TOOLS'],[site.years_label||'8+','YEARS'],[String(count),'PROJECTS'],[String(entries('post').length),'POSTS']];
 return `<main><section class="hero"><div class="hero-inner"><div class="hero-copy"><p class="terminal-intro"><span class="status-dot"></span><span class="command-prefix">${esc(site.intro_terminal?.split(' ')[0]||'febro@workspace:~$')}</span> ${esc(site.intro_terminal?.split(' ').slice(1).join(' ')||'whoami')}</p><h1>${esc(site.site_name)}</h1><h2>${esc(site.hero_roles)}</h2><p class="hero-description">${esc(site.hero_description)}</p><div class="hero-actions"><a href="/cv" class="button primary">View CV ${icon('arrow',14)}</a><a href="/posts" class="button secondary">Read the blog</a>${linkout(site.github,icon('github',13)+' GitHub','button ghost')}</div></div><div class="hero-right"><div class="avatar-orbit"><div class="avatar-circle">${avatar(site)}</div><span class="avatar-online" title="Available"></span></div><div class="hero-stats">${stats.map(([num,label])=>`<div><strong>${esc(num)}</strong><span>${label}</span></div>`).join('')}</div></div></div><a class="hero-down" href="#highlights" aria-label="Scroll to highlights">${icon('down',16)}</a></section><section class="highlights-section" id="highlights"><div class="content-width home-columns"><div>${sectionHead('most read','Popular posts','/posts')}<div class="post-compact-list">${posts.length?posts.map(p=>postCard(p,true)).join(''):'<p>No published posts yet.</p>'}</div></div><div>${sectionHead('selected work','Projects','/portfolio')}<div class="home-project-list">${projects.map((p,i)=>{const href=projectLink(p),tag=href?'a':'div';return `<${tag} ${href?`href="${esc(href)}"`:""} ${accessMode(p)==="external"?'target="_blank" rel="noopener noreferrer"':""} class="home-project ${href?"":"home-project-static"}"><span class="home-project-num">${String(i+1).padStart(2,'0')}</span><div><span class="home-project-label">${esc(p.category)}</span> <span class="mini-year">${esc(p.year)}</span><strong>${esc(p.title)}</strong><div class="tag-row">${pilltags(p.tags)}</div></div></${tag}>`}).join('')}</div></div></div></section></main>`;}
function postsPage(){const items=entries('post'),cats=[...new Set(items.map(p=>p.category))];return `<main class="inner-page content-width">${titleBlock(`${items.length} posts`,'Blog','Notes about maintenance, digital tools, software development, and practical technology.')}<div class="filter-tools"><label class="filter-input">${icon('search',16)}<input id="collection-search" type="search" placeholder="Search posts..." aria-label="Search blog posts"></label><div class="segmented" id="sort-posts"><button class="selected" data-sort="newest">Newest</button><button data-sort="oldest">Oldest</button><button data-sort="popular">Popular</button></div></div><div class="filter-chips" id="collection-categories"><button class="active" data-category="all">All <span>${items.length}</span></button>${cats.map(cat=>`<button data-category="${esc(cat)}">${esc(cat)} <span>${items.filter(p=>p.category===cat).length}</span></button>`).join('')}</div><div class="post-list" id="filter-collection">${items.map(x=>`<div data-title="${esc([x.title,x.description,x.tags].join(' ').toLowerCase())}" data-category="${esc(x.category)}" data-id="${x.id}" data-views="${x.views}">${postCard(x)}</div>`).join('')}</div><p class="empty-state" id="filter-empty" hidden>No matching posts found.</p></main>`;}
function portfolioPage(){const items=entries('project'),groups=getCategories();let globalIndex=0;
 const sections=groups.map(cat=>{const projects=items.filter(x=>x.category.toLowerCase()===cat.name.toLowerCase());if(!projects.length)return '';return `<section class="portfolio-section" id="category-${cat.id}"><div class="portfolio-section-head"><div><div class="eyebrow">// ${esc(cat.name)}</div><h2>${esc(cat.name)}</h2></div><span>${projects.length} projects</span></div><div class="project-grid">${projects.map(x=>projectCard(x,globalIndex++)).join('')}</div></section>`;}).join('');const others=items.filter(x=>!groups.some(c=>c.name.toLowerCase()===x.category.toLowerCase()));
 return `<main class="inner-page content-width">${titleBlock("selected work",'Portfolio','Open-source work, independent products and selected corporate projects. Some are presented as summaries only.')}<nav class="portfolio-jump" aria-label="Project categories">${groups.filter(c=>items.some(x=>x.category.toLowerCase()===c.name.toLowerCase())).map(c=>`<a href="#category-${c.id}">${esc(c.name)}</a>`).join('')}</nav>${sections}${others.length?`<section class="portfolio-section"><div class="portfolio-section-head"><h2>Other projects</h2></div><div class="project-grid">${others.map(x=>projectCard(x,globalIndex++)).join('')}</div></section>`:''}</main>`;}
function automationPage(){const items=entries('automation');return `<main class="inner-page content-width">${titleBlock('workflow & integrations','Automation','Practical workflows connecting equipment, people and digital systems.')}<div class="automation-intro"><div class="eyebrow">// approach</div><p>Identify repetitive work, simplify the steps, automate carefully, and keep the result easy to maintain.</p></div><div class="project-grid automation-grid">${items.map((x,i)=>projectCard(x,i)).join('')}</div></main>`;}
function toolsPage(){const items=visibleTools(),cats=['IT','Electricity'];const cat=x=>x.category==='Electricity'?'Electricity':'IT';return `<main class="inner-page content-width">${titleBlock(`${items.length} utilities`,'Tools','Essential IT and electrical engineering calculators. All calculations open instantly in a modal and run locally in your browser.')}<div class="filter-tools"><label class="filter-input">${icon('search',16)}<input id="collection-search" type="search" placeholder="Search tools..." aria-label="Search tools"></label></div><div class="filter-chips" id="collection-categories"><button class="active" data-category="all">All <span>${items.length}</span></button>${cats.map(c=>`<button data-category="${c}">${c} <span>${items.filter(t=>cat(t)===c).length}</span></button>`).join('')}</div><div class="tool-grid" id="filter-collection">${items.map(x=>`<button type="button" class="tool-card" data-open-tool="${esc(x.slug)}" data-tool-title="${esc(x.title)}" data-tool-desc="${esc(x.description)}" data-title="${esc([x.title,x.description,x.tags].join(' ').toLowerCase())}" data-category="${cat(x)}"><span class="tool-icon">${icon(cat(x)==='Electricity'?'cpu':'terminal',19)}</span><span class="tool-info"><strong>${esc(x.title)}</strong><small>${esc(x.description)}</small></span><span class="tool-type">${cat(x)}</span></button>`).join('')}</div><p class="empty-state" id="filter-empty" hidden>No matching tools found.</p></main><div class="tool-modal" id="tool-modal" aria-hidden="true"><div class="tool-modal-dialog" role="dialog" aria-modal="true" aria-labelledby="tool-modal-title"><div class="tool-modal-head"><span class="tool-icon">${icon('terminal',21)}</span><div><h2 id="tool-modal-title"></h2><p id="tool-modal-description"></p></div><button class="tool-modal-close" type="button" aria-label="Close tool">${icon('close',19)}</button></div><div class="tool-workspace" data-tool=""><div id="tool-inputs"></div><div class="tool-output-block"><div class="tool-output-title">Result <button class="copy-tool" type="button">${icon('copy',14)} Copy</button></div><pre id="tool-output" aria-live="polite">Ready.</pre></div></div></div></div>`;}
function aboutPage(site){let skillMap={};try{skillMap=JSON.parse(site.skills_json);}catch{}return `<main class="inner-page content-width about-page"><div class="about-heading"><div class="about-mini-avatar">${avatar(site,true)}<span class="avatar-online small-online"></span></div><div><div class="eyebrow">// about</div><h1>${esc(site.site_name)}</h1><p>${esc(site.site_tagline)} · ${esc(site.location)}</p></div></div><div class="about-grid"><div class="about-main"><p class="about-description">${esc(site.about_description)}</p><div class="availability-box"><div class="eyebrow"><span class="status-dot"></span> currently</div><strong>${esc(site.availability)}</strong><small>${esc(site.location)}</small></div><div class="about-links">${linkout(site.github,'GitHub','small-link')}${site.linkedin?linkout(site.linkedin,'LinkedIn','small-link'):''}<a class="small-link" href="mailto:${esc(site.email)}">Email</a><a class="small-link" href="/contact">Contact</a></div></div><div class="about-skills">${Object.entries(skillMap).map(([k,list])=>`<div class="skill-group"><div class="eyebrow">// ${esc(k)}</div><div class="skill-tags">${list.map(x=>badge(x)).join('')}</div></div>`).join('')}</div></div><div class="off-clock"><div class="eyebrow">// off the clock</div><strong>Building things that solve actual problems</strong><p>Outside of industrial maintenance, I explore web apps, automation, Raspberry Pi projects and open-source software. My goal is to connect practical engineering with digital tools that make everyday work more efficient.</p></div></main>`;}
function cvPage(site){const synced=cvSync.get().records;const experience=synced.experience??entries('experience'),education=synced.education??entries('education'),certs=synced.certification??entries('certification');let skillMap={};try{skillMap=JSON.parse(site.skills_json)}catch{}return `<main class="inner-page content-width cv-page"><div class="cv-heading"><div>${titleBlock('curriculum vitae',site.site_name,site.cv_summary)}</div><button type="button" class="button primary download-button" data-open-cv-request>${icon('mail',15)} Request CV</button></div><div class="cv-grid"><div><h2 class="cv-section-label">EXPERIENCE</h2><div class="timeline">${experience.map(x=>`<article class="timeline-item"><div class="timeline-period">${esc(x.period)} · ${esc(site.location)}</div><h3>${esc(x.title)}</h3><a class="timeline-company" href="/about">${esc(x.company)}</a><p>${esc(x.description)}</p>${x.body?`<ul>${x.body.split(/\n/).filter(Boolean).map(b=>`<li>${esc(b)}</li>`).join('')}</ul>`:''}</article>`).join('')}</div><h2 class="cv-section-label">EDUCATION</h2><div class="timeline">${education.map(x=>`<article class="timeline-item"><div class="timeline-period">${esc(x.period)}</div><h3>${esc(x.title)}</h3><div class="timeline-company">${esc(x.company)}</div><p>${esc(x.description)}</p></article>`).join('')}</div></div><aside><h2 class="cv-section-label">CORE SKILLS</h2>${Object.entries(skillMap).map(([k,values])=>`<div class="cv-skill"><strong>${esc(k)}</strong><p>${esc(values.join(', '))}</p></div>`).join('')}<h2 class="cv-section-label cv-cert-label">CERTIFICATIONS</h2>${certs.map(x=>`<div class="certificate">${icon('shield',15)}<div><strong>${esc(x.title)}</strong><p>${esc(x.company)}</p></div></div>`).join('')}</aside></div><p class="cv-source-note">${cvSync.get().status==='synced'?'Experience, education and certifications are read from PocketBase.':'Experience, education and certifications listed above are from my public career profile.'} Additional public profile: <a href="https://profile.febro.id" target="_blank" rel="noopener noreferrer">profile.febro.id ↗</a>. This CV uses the synced source when configured; otherwise the locally managed CV is displayed.</p></main><div class="tool-modal cv-request-modal" id="cv-request-modal" aria-hidden="true"><div class="tool-modal-dialog" role="dialog" aria-modal="true" aria-labelledby="cv-request-title"><div class="tool-modal-head"><span class="tool-icon">${icon('mail',20)}</span><div><h2 id="cv-request-title">Request my CV</h2><p>Tell me where I can send the CV. No public download.</p></div><button class="cv-modal-close" type="button" aria-label="Close request form">${icon('close',19)}</button></div><form id="cv-request-form" class="cv-request-form"><label>Full name<input name="name" required maxlength="120" autocomplete="name"></label><label>Work email<input name="email" type="email" maxlength="200" required autocomplete="email"></label><label>Company / purpose<input name="company" maxlength="160" required></label><label>Message (optional)<textarea name="message" maxlength="1000" rows="3"></textarea></label><label class="cv-honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><button type="submit" class="button primary">Send request →</button><p id="cv-request-status" role="status" aria-live="polite"></p></form></div></div>`;}
function detailPage(site,item,kind){const paths={project:'/portfolio',post:'/posts'};const back=paths[kind],related=entries(kind).filter(x=>x.id!==item.id&&(kind!=='project'||accessMode(x)==='detail')).slice(0,3);if(kind==='post'){db.prepare('UPDATE entries SET views=views+1 WHERE id=?').run(item.id);}return `<main class="inner-page content-width detail-page"><a class="back-link" href="${back}">← Back to ${kind==='post'?'Blog':kind==='project'?'Portfolio':'Automation'}</a><div class="eyebrow">// ${esc(item.category||kind)} · ${esc(item.year)}</div><h1>${esc(item.title)}</h1><p class="detail-subtitle">${esc(item.description)}</p><div class="tag-row">${pilltags(item.tags)}</div>${item.url?`<div class="detail-actions">${linkout(item.url,'Visit project '+icon('external',15),'button primary')}</div>`:''}<div class="article-body">${item.body?plainMarkdown(item.body):`<p>${esc(item.description)}</p>`}</div>${related.length?`<div class="related-items">${sectionHead('more to explore',kind==='post'?'More posts':'Other projects',back)}<div class="related-grid">${related.map(x=>`<a href="${back}/${esc(x.slug)}"><span class="eyebrow">// ${esc(x.category)}</span><strong>${esc(x.title)}</strong><p>${esc(x.description)}</p></a>`).join('')}</div></div>`:''}</main>`;}
const BUILTIN_TOOLS = new Set('ip-calculator dns-records http-status url-encoder base64 json-formatter jwt-decoder sha256 password-generator uuid-generator unix-timestamp cron-helper nginx-generator pm2-generator systemd-generator ufw-generator ssh-command gitignore-generator text-tools slug-generator color-converter chmod-calculator random-number regex-tester url-parser ipv4-binary ip-range-checker port-reference mac-formatter dns-zone-generator apache-vhost-generator htaccess-generator dockerfile-generator docker-compose-generator kubernetes-manifest github-actions-workflow ansible-playbook-generator security-headers-generator csp-generator password-strength html-escape'.split(' '));
function toolDetail(site,item){
 if(!BUILTIN_TOOLS.has(item.slug)) return `<main class="inner-page content-width tool-detail-page"><a class="back-link" href="/tools">← All tools</a><div class="eyebrow">// ${esc(item.category)} / custom tool</div><h1>${esc(item.title)}</h1><p>${esc(item.description)}</p>${item.url?`<div class="detail-actions">${linkout(item.url,'Open utility '+icon('external',14),'button primary')}</div>`:'<div class="automation-intro" style="margin-top:25px">This tool has not been configured. Add a working external URL in the admin dashboard or implement it before publishing.</div>'}</main>`;
 return `<main class="inner-page content-width tool-detail-page"><a class="back-link" href="/tools">← All tools</a><div class="eyebrow">// ${esc(item.category)} / browser utility</div><h1>${esc(item.title)}</h1><p>${esc(item.description)}</p><div class="tool-workspace" data-tool="${esc(item.slug)}"><div class="tool-workspace-title"><span class="tool-icon">${icon('terminal',18)}</span><div><strong>Interactive workspace</strong><small>Inputs are processed locally in your browser unless stated otherwise.</small></div></div><div id="tool-inputs"></div><div class="tool-output-block"><div class="tool-output-title">Output <button class="copy-tool" type="button">${icon('copy',14)} Copy</button></div><pre id="tool-output">Ready when you are.</pre></div></div></main>`;}
function contactPage(site){return `<main class="inner-page content-width contact-page">${titleBlock('get in touch','Contact','Have a project, a question or an opportunity? Send me a message — it goes directly to my inbox.')}<div class="contact-layout"><div class="contact-intro"><p>You can also contact me directly via <a href="mailto:${esc(site.email)}">${esc(site.email)}</a>.</p><div class="contact-methods">${linkout(site.github,icon('github',15)+' GitHub','small-link')}${site.linkedin?linkout(site.linkedin,'LinkedIn','small-link'):''}</div></div><form id="contact-form" class="contact-form"><div class="contact-form-row"><label><span>Name *</span><input type="text" name="name" required maxlength="120" autocomplete="name" placeholder="Your name"></label><label><span>Email *</span><input type="email" name="email" required maxlength="200" autocomplete="email" placeholder="you@example.com"></label></div><label><span>Phone (optional)</span><input type="tel" name="phone" maxlength="40" autocomplete="tel" placeholder="+62..."></label><label><span>Message *</span><textarea name="message" required maxlength="3000" minlength="10" rows="6" placeholder="What's on your mind?"></textarea></label><label class="cv-honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><div class="contact-submit"><button type="submit" class="button primary">Send message ${icon('arrow',16)}</button><span class="contact-status" id="contact-status" role="status" aria-live="polite"></span></div></form></div></main>`;}
const adminKinds={post:'Blog Posts',project:'Projects',tool:'Tools',experience:'Experience',education:'Education',certification:'Certifications'};
function adminShell(inner,title='Overview',auth){const site=getSettings();if(!auth)return `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta charset="utf-8"><title>Admin Login — ${esc(site.site_name)}</title><link rel="stylesheet" href="/app.css?v=1.4.0"></head><body class="admin-page"><main class="admin-login"><a class="brand" href="/"><span class="brand-mark">fh</span><span class="brand-path">~/febro</span></a>${inner}</main><script src="/app.js?v=1.4.0" defer></script></body></html>`;
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>${esc(title)} — CMS</title><link rel="stylesheet" href="/app.css?v=1.4.0"></head><body class="admin-page"><div class="admin-layout"><aside class="admin-sidebar"><a class="brand" href="/admin"><span class="brand-mark">fh</span><span class="brand-path">~/cms</span></a><p class="admin-side-label">WORKSPACE</p><a href="/admin" class="${title==='Overview'?'admin-active':''}">Overview</a><a href="/admin/settings" class="${title==='Settings'?'admin-active':''}">Profile & Settings</a><a href="/admin/cv-requests" class="${title==='CV requests'?'admin-active':''}">CV requests</a><a href="/admin/contact-messages" class="${title==='Contact messages'?'admin-active':''}">Contact inbox</a><a href="/admin/project-categories" class="${title==='Portfolio categories'?'admin-active':''}">Portfolio categories</a><p class="admin-side-label">CONTENT</p>${Object.entries(adminKinds).map(([kind,label])=>`<a href="/admin/content?kind=${kind}" class="${title===label?'admin-active':''}">${esc(label)}</a>`).join('')}<div class="sidebar-bottom"><a href="/" target="_blank">View website ${icon('external',13)}</a><form method="post" action="/admin/logout"><input type="hidden" name="_csrf" value="${esc(auth.csrf)}"><button type="submit">${icon('logout',15)} Sign out</button></form></div></aside><main class="admin-content"><header class="admin-topbar"><button class="admin-menu-toggle" type="button">${icon('menu',18)}</button><span>Febro Personal / ${esc(title)}</span><span class="admin-account">${esc(auth.email)}</span></header>${inner}</main></div><script src="/app.js?v=1.4.0" defer></script></body></html>`;
}
function adminOverview(auth){const all=Object.keys(adminKinds).map(k=>({kind:k,count:entries(k,false).length}));return adminShell(`<div class="admin-page-title"><div><div class="eyebrow">// control center</div><h1>Overview</h1><p>Manage your personal website content and configuration.</p></div><a href="/" class="button secondary" target="_blank">Open public site ${icon('external',14)}</a></div><div class="admin-stat-grid">${all.slice(0,4).map(x=>`<a href="/admin/content?kind=${x.kind}" class="admin-stat"><span>${esc(adminKinds[x.kind])}</span><strong>${x.count}</strong><small>Manage records →</small></a>`).join('')}</div><div class="admin-panel"><div class="panel-title"><h2>Content management</h2><span>Everything in one place</span></div><div class="admin-shortcuts">${all.map(x=>`<a href="/admin/content?kind=${x.kind}"><span>${esc(adminKinds[x.kind])}</span><span>${x.count} items ${icon('arrow',13)}</span></a>`).join('')}</div></div><div class="admin-help">Your changes are saved to <code>data/profile.sqlite</code>. The public pages update immediately. Keep a database backup before major changes.</div>`, 'Overview',auth);}
const profileFields=[
 ['site_name','Full name','text'],['site_tagline','Professional tagline','text'],['hero_roles','Homepage roles (headline)','text'],['hero_description','Homepage introduction','textarea'],['intro_terminal','Terminal greeting','text'],['about_description','About description','textarea'],['availability','Current status','text'],['location','Location','text'],['years_label','Years label','text'],['cv_summary','CV summary','textarea'],['email','Contact email','email'],['github','GitHub URL','url'],['linkedin','LinkedIn URL','url'],['website','Main domain for SEO','url'],['footer_note','Footer note','text'],['skills_json','Skill groups (JSON)','textarea']
];
function adminSettings(auth,notice=''){const site=getSettings();return adminShell(`<div class="admin-page-title"><div><div class="eyebrow">// identity & configuration</div><h1>Profile & Settings</h1><p>Edit your public profile, links, skills and profile photograph.</p></div></div>${notice?`<div class="admin-notice">${esc(notice)}</div>`:''}<form method="post" action="/admin/settings" class="admin-panel settings-form" id="profile-settings-form"><input type="hidden" name="_csrf" value="${esc(auth.csrf)}">${profileFields.map(([name,label,type])=>`<label class="form-field"><span>${esc(label)}</span>${type==='textarea'?`<textarea name="${name}" rows="${name==='skills_json'?9:4}" ${name==='skills_json'?'spellcheck="false"':''}>${esc(site[name]||'')}</textarea>`:`<input type="${type}" name="${name}" value="${esc(site[name]||'')}">`}</label>`).join('')}<div class="form-field"><span>Profile image (JPG, PNG, WEBP; up to 1.5 MB)</span><div class="avatar-settings-preview">${avatar(site,true)}</div><input id="avatar-upload" type="file" accept="image/jpeg,image/png,image/webp"><input type="hidden" name="avatar_data" id="avatar-data"><label class="check-row"><input type="checkbox" name="remove_avatar" value="1"> Remove existing profile image</label></div><div class="admin-form-actions"><button class="button primary" type="submit">Save settings ${icon('check',15)}</button></div></form>`, 'Settings',auth);}
function adminCollection(auth,kind,notice=''){const items=entries(kind,false);return adminShell(`<div class="admin-page-title"><div><div class="eyebrow">// content management</div><h1>${esc(adminKinds[kind])}</h1><p>${items.length} records · edit, publish, organize or remove entries.</p></div><a class="button primary" href="/admin/content/new?kind=${kind}">+ New entry</a></div>${notice?`<div class="admin-notice">${esc(notice)}</div>`:''}<div class="admin-panel admin-table-scroll"><table class="admin-table"><thead><tr><th>Title</th><th>Category</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${esc(x.title)}</strong><small>/${esc(x.slug)}</small></td><td>${esc(x.category||'—')}</td><td>${x.enabled?badge('Published','state-live'):badge('Hidden')}</td><td>${esc(x.updated_at.slice(0,10))}</td><td><div class="row-actions"><a href="/admin/content/${x.id}/edit">Edit</a><form method="post" action="/admin/content/${x.id}/delete" onsubmit="return confirm('Delete this item permanently?')"><input type="hidden" name="_csrf" value="${esc(auth.csrf)}"><input type="hidden" name="kind" value="${kind}"><button type="submit" class="danger-link">Delete</button></form></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty-state">No records yet. Create your first entry.</td></tr>'}</tbody></table></div>`,adminKinds[kind],auth);}
const entryFields=[
 ['title','Title','text'],['slug','URL slug','text'],['subtitle','Subtitle','text'],['description','Short description','textarea'],['body','Full content / notes (simple Markdown supported)','textarea'],['category','Category','text'],['tags','Tags (comma-separated)','text'],['company','Company / institution','text'],['year','Year','text'],['period','Date range','text'],['url','External URL (optional)','url']
];
function adminEdit(auth,kind,item,notice=''){const isNew=!item;item=item||{};return adminShell(`<div class="admin-page-title"><div><div class="eyebrow">// ${esc(adminKinds[kind])}</div><h1>${isNew?'New entry':'Edit entry'}</h1><p>All fields are optional except title and URL slug.</p></div><a href="/admin/content?kind=${kind}" class="button secondary">← Back</a></div>${notice?`<div class="admin-error">${esc(notice)}</div>`:''}<form class="admin-panel settings-form" method="post" action="/admin/content/save"><input type="hidden" name="_csrf" value="${esc(auth.csrf)}"><input type="hidden" name="id" value="${esc(item.id||'')}"><input type="hidden" name="kind" value="${kind}">${kind==='project'?`<label class="form-field"><span>Portfolio access</span><select name="access_mode"><option value="view_only" ${accessMode(item)==='view_only'?'selected':''}>View only — no detail or external links</option><option value="detail" ${accessMode(item)==='detail'?'selected':''}>Open detail page on febro.id</option><option value="external" ${accessMode(item)==='external'?'selected':''}>External preview — link to live app</option></select><small>Projects involving employers should usually be View only.</small></label>`:''}${entryFields.map(([name,label,type])=>`<label class="form-field"><span>${esc(label)}</span>${kind==='project'&&name==='category'?`<select name="category" required><option value="">Choose a category</option>${getCategories().map(c=>`<option value="${esc(c.name)}" ${c.name===item.category?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${name}" rows="${name==='body'?10:4}">${esc(item[name]||'')}</textarea>`:`<input type="${type}" name="${name}" value="${esc(item[name]||'')}" ${name==='title'?'required':''}>`}</label>`).join('')}<div class="form-row"><label class="check-row"><input type="checkbox" name="enabled" value="1" ${!isNew?!item.enabled?'':'checked':kind==='tool'?'':'checked'}> Published / visible</label><label class="check-row"><input type="checkbox" name="featured" value="1" ${item.featured?'checked':''}> Featured</label></div><div class="admin-form-actions"><button class="button primary" type="submit">${isNew?'Create entry':'Save changes'} ${icon('check',15)}</button><a class="button secondary" href="/admin/content?kind=${kind}">Cancel</a></div></form>`,adminKinds[kind],auth);}

function categoryAdmin(auth,notice=''){const cats=getCategories();const count=db.prepare("SELECT category,COUNT(*) n FROM entries WHERE kind='project' GROUP BY category").all();return adminShell(`<div class="admin-page-title"><div><div class="eyebrow">// portfolio organization</div><h1>Portfolio categories</h1><p>Create your own sections and arrange their order on febro.id/portfolio.</p></div></div>${notice?`<div class="admin-notice">${esc(notice)}</div>`:''}<div class="admin-panel admin-table-scroll"><table class="admin-table"><thead><tr><th>Position</th><th>Category</th><th>Projects</th><th>Change order</th><th>Actions</th></tr></thead><tbody>${cats.map((c,i)=>`<tr><td>${i+1}</td><td><strong>${esc(c.name)}</strong></td><td>${count.find(k=>k.category.toLowerCase()===c.name.toLowerCase())?.n||0}</td><td><div class="category-actions">${['up','down'].map(dir=>`<form method="post" action="/admin/project-categories/move"><input type="hidden" name="_csrf" value="${esc(auth.csrf)}"><input type="hidden" name="id" value="${c.id}"><input type="hidden" name="direction" value="${dir}"><button type="submit" class="button secondary" ${dir==='up'&&i===0||dir==='down'&&i===cats.length-1?'disabled':''}>${dir==='up'?'↑ Up':'↓ Down'}</button></form>`).join('')}</div></td><td><form method="post" action="/admin/project-categories/rename" class="category-rename"><input type="hidden" name="_csrf" value="${esc(auth.csrf)}"><input type="hidden" name="id" value="${c.id}"><input name="name" aria-label="Rename ${esc(c.name)}" maxlength="60" value="${esc(c.name)}" required><button type="submit" class="button secondary">Rename</button></form><form method="post" action="/admin/project-categories/delete" onsubmit="return confirm('Delete empty category?')"><input type="hidden" name="_csrf" value="${esc(auth.csrf)}"><input type="hidden" name="id" value="${c.id}"><button class="danger-link" type="submit">Delete</button></form></td></tr>`).join('')}</tbody></table></div><form class="admin-panel category-create" method="post" action="/admin/project-categories/add"><label class="form-field"><span>New category name</span><input name="name" maxlength="60" required placeholder="e.g. Open Source, Corporate, Personal"></label><button class="button primary" type="submit">+ Add category</button><input type="hidden" name="_csrf" value="${esc(auth.csrf)}"></form><div class="admin-help">Categories are separate public portfolio sections. A category cannot be deleted while it contains projects. Rename and order changes appear on the public website immediately.</div>`, 'Portfolio categories',auth);}
function contactAdmin(auth){const msgs=db.prepare('SELECT * FROM contact_messages ORDER BY id DESC LIMIT 150').all();return adminShell(`<div class="admin-page-title"><div><div class="eyebrow">// messages</div><h1>Contact inbox</h1><p>Messages submitted through the public Contact form.</p></div></div><div class="admin-panel admin-table-scroll"><table class="admin-table"><thead><tr><th>Received</th><th>Sender</th><th>Message</th><th>Email</th></tr></thead><tbody>${msgs.map(m=>`<tr><td>${esc(m.created_at)}</td><td><strong>${esc(m.name)}</strong><small>${esc(m.email)}${m.phone?' · '+esc(m.phone):''}</small></td><td style="white-space:pre-wrap;max-width:620px">${esc(m.message)}</td><td>${esc(m.delivery_status)}</td></tr>`).join('')||'<tr><td colspan="4">No messages received yet.</td></tr>'}</tbody></table></div>`, 'Contact messages',auth);}

function send(res,status,body,type='text/html; charset=utf-8',more={}){res.writeHead(status,{'Content-Type':type,'X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','X-Frame-Options':'DENY','Permissions-Policy':'camera=(),microphone=(),geolocation=()','Cache-Control': type.startsWith('text/html')?'no-cache, must-revalidate':'public, max-age=300', 'Content-Security-Policy':"default-src 'self'; img-src 'self' data:; font-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'",...more});res.end(body);}
function redirect(res,href,extra={}){res.writeHead(303,{Location:href,...extra});res.end();}
async function readForm(req){let bytes=0,chunks=[];for await(const chunk of req){bytes+=chunk.length;if(bytes>2_100_000)throw new Error('Request too large (2 MB limit)');chunks.push(chunk);}return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString('utf8')));}
function cookies(req){return Object.fromEntries((req.headers.cookie||'').split(';').map(s=>{const i=s.indexOf('=');return i<0?['','']:[s.slice(0,i).trim(),s.slice(i+1).trim()]}));}
const hash=t=>crypto.createHash('sha256').update(t).digest('hex');
function getAuth(req){const token=cookies(req).fh_admin;if(!token||!(/^[a-f0-9]{64}$/.test(token)))return null;const record=db.prepare('SELECT admins.id,admins.email,sessions.csrf,sessions.expires_at FROM sessions JOIN admins ON admins.id=sessions.admin_id WHERE token_hash=?').get(hash(token));if(!record||record.expires_at<Date.now())return null;return record;}
function newSession(req,res,adminId){const token=crypto.randomBytes(32).toString('hex'),csrf=crypto.randomBytes(24).toString('hex'),expiration=Date.now()+7*24*60*60*1000;db.prepare('INSERT INTO sessions(token_hash,admin_id,csrf,expires_at) VALUES (?,?,?,?)').run(hash(token),adminId,csrf,expiration);const secure=process.env.COOKIE_SECURE==='1'||req.headers['x-forwarded-proto']==='https';return `fh_admin=${token}; HttpOnly; SameSite=Lax; Path=/; Max-Age=604800${secure?'; Secure':''}`;}
const csrfValid=(auth,fields)=>Boolean(auth&&fields&&fields._csrf&&crypto.timingSafeEqual(Buffer.from(String(fields._csrf).padEnd(48).slice(0,48)),Buffer.from(auth.csrf.padEnd(48).slice(0,48)))&&fields._csrf===auth.csrf);
const loginAttempts=new Map();
function loginPage(error=''){const count=db.prepare('SELECT COUNT(*) AS n FROM admins').get().n;return adminShell(`<div class="eyebrow">// admin access</div><h1>Welcome back.</h1><p>Sign in to manage your personal website.</p>${error?`<div class="admin-error">${esc(error)}</div>`:''}${count===0?'<div class="admin-help">No admin exists yet. Create one on your VPS with <code>npm run admin:create -- --email you@example.com</code></div>':''}<form action="/admin/login" method="post" class="login-form"><label class="form-field"><span>Email</span><input type="email" name="email" placeholder="you@example.com" autocomplete="username" required></label><label class="form-field"><span>Password</span><input type="password" name="password" autocomplete="current-password" required></label><button class="button primary" type="submit">Sign in ${icon('arrow',15)}</button></form><a class="back-link" href="/">← Return to website</a>`, 'Login',null);}
const MIME={'.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.svg':'image/svg+xml','.png':'image/png','.jpeg':'image/jpeg','.jpg':'image/jpeg','.webp':'image/webp','.txt':'text/plain; charset=utf-8'};
function staticFile(pathname,res){if(!/^\/(app\.css|app\.js|favicon\.svg|uploads\/[a-z0-9._-]+)$/.test(pathname))return false;const file=path.join(ROOT,pathname);if(!file.startsWith(ROOT+path.sep))return false;try{const stats=fs.statSync(file);if(!stats.isFile()||stats.size>5_000_000)return false;return send(res,200,fs.readFileSync(file),MIME[path.extname(file)]||'application/octet-stream',{'Cache-Control':pathname.startsWith('/uploads/')?'public, max-age=86400':'no-cache, must-revalidate'}),true;}catch{return false;}}
function saveAvatar(data){
 if(!data)return null;
 const m=/^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/=]+)$/.exec(data);
 if(!m)throw new Error('Invalid image format');
 const buffer=Buffer.from(m[2],'base64');
 if(buffer.length>1_500_000||buffer.length<100)throw new Error('Image must be smaller than 1.5 MB');
 let ext;
 if(buffer.subarray(0,3).toString('hex')==='ffd8ff')ext='jpg';
 else if(buffer.subarray(0,8).toString('hex')==='89504e470d0a1a0a')ext='png';
 else if(buffer.subarray(0,4).toString('ascii')==='RIFF'&&buffer.subarray(8,12).toString('ascii')==='WEBP'&&['VP8 ','VP8L','VP8X'].includes(buffer.subarray(12,16).toString('ascii')))ext='webp';
 else throw new Error('Unsupported or invalid image data. Please use JPG, PNG or WebP.');
 const f=`portrait-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.${ext}`;
 fs.writeFileSync(path.join(ROOT,'uploads',f),buffer,{mode:0o644});return '/uploads/'+f;
}
const validEmail=s=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s) && s.length<=200;
const validOrigin=req=>{const origin=req.headers.origin;return !origin||origin===mail.baseUrl()||/^http:\/\/127\.0\.0\.1:\d+$/.test(origin)};
const hashedIP=req=>crypto.createHash('sha256').update(String(req.headers['x-forwarded-for']||req.socket.remoteAddress||'unknown').split(',')[0].trim()).digest('hex');
const jsonResponse=(res,status,obj)=>send(res,status,JSON.stringify(obj),'application/json; charset=utf-8',{'Cache-Control':'no-store'});
async function handleCVRequest(req,res){
 if(req.headers['content-type']?.split(';')[0]!=='application/x-www-form-urlencoded')return jsonResponse(res,415,{error:'Invalid form format'});
 if(!validOrigin(req))return jsonResponse(res,403,{error:'Invalid origin'});
 const p=await readForm(req);if(p.website)return jsonResponse(res,200,{ok:true});
 const record={name:String(p.name||'').trim().slice(0,120),email:String(p.email||'').trim().toLowerCase(),company:String(p.company||'').trim().slice(0,160),message:String(p.message||'').trim().slice(0,1000)};
 if(record.name.length<2||!validEmail(record.email)||record.company.length<2)return jsonResponse(res,400,{error:'Enter name, email and organization / purpose.'});
 const ip=hashedIP(req);if(db.prepare("SELECT COUNT(*) n FROM cv_requests WHERE ip_hash=? AND created_at>=datetime('now','-1 day')").get(ip).n>=4)return jsonResponse(res,429,{error:'Daily request limit reached. Please try tomorrow.'});
 const result=db.prepare('INSERT INTO cv_requests(name,email,company,message,ip_hash) VALUES(?,?,?,?,?)').run(record.name,record.email,record.company,record.message,ip);
 record.id=Number(result.lastInsertRowid);
 try{await mail.requestNotification(record);db.prepare("UPDATE cv_requests SET delivery_status='emailed' WHERE id=?").run(record.id)}catch(err){console.error('[CV admin notification]',err.message);db.prepare("UPDATE cv_requests SET delivery_status='email_failed' WHERE id=?").run(record.id)}
 return jsonResponse(res,200,{ok:true,message:'Request received. You will get a download link by email if your request is approved.'});
}
async function handleContact(req,res){
 if(req.headers['content-type']?.split(';')[0]!=='application/x-www-form-urlencoded')return jsonResponse(res,415,{error:'Invalid form format'});
 if(!validOrigin(req))return jsonResponse(res,403,{error:'Invalid origin'});
 const p=await readForm(req);if(p.website)return jsonResponse(res,200,{ok:true});
 const record={name:String(p.name||'').trim().slice(0,120),email:String(p.email||'').trim().toLowerCase(),phone:String(p.phone||'').trim().slice(0,40),message:String(p.message||'').trim().slice(0,3000)};
 if(record.name.length<2||!validEmail(record.email)||record.message.length<10)return jsonResponse(res,400,{error:'Please enter a valid name, email and message (at least 10 characters).'});
 const ip=hashedIP(req);if(db.prepare("SELECT COUNT(*) n FROM contact_messages WHERE ip_hash=? AND created_at>=datetime('now','-1 day')").get(ip).n>=5)return jsonResponse(res,429,{error:'Daily message limit reached.'});
 const result=db.prepare('INSERT INTO contact_messages(name,email,phone,message,ip_hash) VALUES(?,?,?,?,?)').run(record.name,record.email,record.phone,record.message,ip);record.id=Number(result.lastInsertRowid);
 try{await mail.contactNotification(record);db.prepare("UPDATE contact_messages SET delivery_status='emailed' WHERE id=?").run(record.id)}catch(err){console.error('[Contact notification]',err.message);db.prepare("UPDATE contact_messages SET delivery_status='email_failed' WHERE id=?").run(record.id)}
 return jsonResponse(res,200,{ok:true,message:'Message received. Thank you — I will get back to you by email.'});
}
function cvRequestsAdmin(auth,notice=''){const rows=db.prepare('SELECT * FROM cv_requests ORDER BY id DESC LIMIT 150').all();const sync=cvSync.get();const ready=mail.smtpReady();return adminShell(`<div class="admin-page-title"><div><div class="eyebrow">// private inbox</div><h1>CV requests</h1><p>Approve requests to automatically email a 72-hour CV PDF download link. Revoke any link at any time.</p></div></div>${notice?`<div class="admin-notice">${esc(notice)}</div>`:''}${!ready?`<div class="admin-error">SMTP is not configured. Set credentials in /opt/febro/.env and restart PM2.</div>`:''}<div class="admin-panel admin-table-scroll"><table class="admin-table"><thead><tr><th>ID / Date</th><th>Requester</th><th>Organization / message</th><th>Status / expiration</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>#${String(x.id).padStart(5,'0')}<small>${esc(x.created_at)}</small></td><td><strong>${esc(x.name)}</strong><small>${esc(x.email)}</small></td><td>${esc(x.company)}<small>${esc(x.message)}</small></td><td><strong>${esc(x.review_status)}</strong><small>Admin email: ${esc(x.delivery_status)}${x.token_expires_at?' · Link expires '+esc(new Date(x.token_expires_at).toISOString().slice(0,16))+' UTC':''}</small></td><td><div class="cv-admin-actions">${['approve','reject','revoke'].filter(action=>action==='approve'?(x.review_status!=='rejected'):action==='reject'?(x.review_status==='pending'||x.review_status==='email_failed'):(x.review_status==='approved')).map(action=>`<form method="post" action="/admin/cv-requests/${x.id}/${action}" ><input type="hidden" name="_csrf" value="${esc(auth.csrf)}"><button class="button ${action==='approve'?'primary':'secondary'}" type="submit">${action==='approve'?(x.review_status==='approved'?'Resend link':'Approve & email'):action==='reject'?'Reject':'Revoke'}</button></form>`).join('')}</div></td></tr>`).join('')||'<tr><td colspan="5">No requests yet.</td></tr>'}</tbody></table></div><div class="admin-help">CV source: <strong>${esc(sync.status)}</strong>. When synchronization is not configured, the existing local Experience, Education and Certification content is used to generate the PDF at download time. The file is not publicly downloadable; only a valid approved link works.</div>`, 'CV requests',auth);}
async function handleCVAdminAction(res,id,action){const record=db.prepare('SELECT * FROM cv_requests WHERE id=?').get(id);if(!record)return send(res,404,'CV request not found');
 if(action==='reject'||action==='revoke'){db.prepare("UPDATE cv_requests SET review_status=?,token_hash='',token_expires_at=0,reviewed_at=CURRENT_TIMESTAMP WHERE id=?").run(action==='reject'?'rejected':'revoked',id);return redirect(res,'/admin/cv-requests?result='+action)}
 if(action!=='approve')return send(res,400,'Invalid action');
 if(!mail.smtpReady())return redirect(res,'/admin/cv-requests?result=smtp_missing');
 const ttl=Math.max(1,Math.min(168,Number(process.env.CV_LINK_TTL_HOURS)||72));const token=crypto.randomBytes(32).toString('hex'),expires=Date.now()+ttl*3600000;
 // Mark approved only after SMTP delivery succeeds. New approvals invalidate old links.
 const link=mail.baseUrl()+'/cv/download/'+token;
 try{await mail.approvedNotification(record,link,ttl);
  db.prepare("UPDATE cv_requests SET review_status='approved',token_hash=?,token_expires_at=?,reviewed_at=CURRENT_TIMESTAMP,sent_at=CURRENT_TIMESTAMP WHERE id=?").run(hash(token),expires,id);
  return redirect(res,'/admin/cv-requests?result=approved');
 }catch(err){console.error('[CV approval email]',err.message);db.prepare("UPDATE cv_requests SET review_status='email_failed',token_hash='',token_expires_at=0 WHERE id=?").run(id);return redirect(res,'/admin/cv-requests?result=email_failed');}
}
function downloadCV(res,token){if(!/^[a-f0-9]{64}$/.test(token))return send(res,404,'Invalid or expired CV link');const r=db.prepare("SELECT id FROM cv_requests WHERE token_hash=? AND review_status='approved' AND token_expires_at>?").get(hash(token),Date.now());if(!r)return send(res,410,'CV link expired or revoked. Please request another CV.','text/plain; charset=utf-8',{'Cache-Control':'no-store'});
 const site=getSettings(),synced=cvSync.get().records;let skills={};try{skills=JSON.parse(site.skills_json||'{}')}catch{}
 const pdf=cvPDF(site,synced.experience??entries('experience'),synced.education??entries('education'),synced.certification??entries('certification'),skills);
 return send(res,200,pdf,'application/pdf',{'Cache-Control':'private, no-store','Content-Disposition':'attachment; filename="Febro-Herdyanto-CV.pdf"','X-Robots-Tag':'noindex, nofollow'});
}

